import { Message } from "./types";

export const inputs = ["/tf_static"];
export const output = "/foxglove/debug";

type FloatMsg = Message<"std_msgs/Float32">;

function getIntegerFromEnd(str: string): number {
  const match = str.match(/\d+$/);
  if (match) {
    // Specify radix 10 for decimal parsing
    return parseInt(match[0], 10);
  }
  return 0;
}

export default function script(event: any, globals: any): FloatMsg | undefined {
  // log(globals);
  return { data: getIntegerFromEnd(output) };
}
